"""Render recorded observer frames only. No model endpoints or credentials."""
import json,sys
from pathlib import Path
root=Path(sys.argv[1]);games={}
for cohort in ['frontier','mainstream']:
 p=root/(cohort+'.jsonl')
 if p.exists():games[cohort]=[json.loads(line) for line in p.read_text().splitlines()]
data=json.dumps(games,separators=(',',':')).replace('<','\\u003c')
html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Whiz 100 · Baseline replay</title>
<style>body{margin:0;background:#0c141c;color:#e8eef2;font:16px system-ui}main{max-width:1180px;margin:auto;padding:24px}h1{margin:0}header{display:flex;justify-content:space-between;gap:20px;align-items:center}.muted{color:#a8b7c5}button,select{background:#243443;color:inherit;border:1px solid #506777;border-radius:7px;padding:9px;cursor:pointer}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:20px 0}input[type=range]{flex:1;min-width:200px}.table{display:grid;grid-template-columns:1fr 1fr;gap:16px}.seat{border:2px solid #344653;background:#142731;border-radius:12px;padding:16px}.active{border-color:#f2c66a}.cards{display:flex;flex-wrap:wrap;gap:5px;margin-top:10px}.card{display:inline-block;background:#f1f2ed;color:#101820;padding:7px;border-radius:5px;font:bold 18px Georgia;min-width:25px;text-align:center}.red{color:#b12436}.center{margin:18px 0;padding:20px;border:1px solid #456557;border-radius:12px;background:#10392d;text-align:center}.scores{font-size:24px}.model{font-size:12px;overflow-wrap:anywhere}.play{display:inline-block;margin:5px}.hidden{display:none!important}#log{white-space:pre-wrap;font:14px monospace;max-height:140px;overflow:auto}@media(max-width:650px){.table{grid-template-columns:1fr}header{display:block}}body.clean .controls,body.clean #log{display:none}</style>
<main><header><div><h1>WHIZ / 100</h1><div class="muted">Strict bidding · Recorded baseline · No API calls</div></div><div id="status"></div></header>
<p class="muted" id="outcome"></p><div class="controls"><select id="cohort"></select><button id="prev">← Step</button><button id="play">Play</button><button id="next">Step →</button><input id="seek" type="range" min="0" value="0"><select id="speed"><option value="1500">1.5s / action</option><option value="500">0.5s / action</option><option value="3000">3s / action</option></select><label><input id="reveal" type="checkbox" checked>Observer hands</label><button id="clean">Recording mode</button></div>
<div class="center"><div class="scores" id="score"></div><div id="detail"></div><div id="trick"></div></div><div class="table" id="seats"></div><p id="decision" class="muted"></p><pre id="log"></pre><p class="muted">Observer-only hand reveal. Models received only their own hand and public history. Fixed partnerships and one game per cohort are not a ranking. Space: play/pause; arrows: step; C: recording mode.</p></main>
<script type="application/json" id="evidence">__DATA__</script><script>
const data=JSON.parse(document.getElementById('evidence').textContent),$=id=>document.getElementById(id);let frames=[],index=0,timer=null,models=[];
function card(c){const suits={C:'♣',D:'♦',H:'♥',S:'♠'},e=document.createElement('span');e.className='card'+('DH'.includes(c[1])?' red':'');e.textContent=(c[0]==='T'?'10':c[0])+suits[c[1]];return e;}
function render(){const f=frames[index],s=f.snapshot;$('seek').value=index;$('score').textContent=`North + South ${s.scores[0]} : ${s.scores[1]} East + West`;$('detail').textContent=`Hand ${s.handNumber} · ${s.phase} · Bags ${s.bags.join(' / ')} · ${s.spadesBroken?'Spades broken':'Spades unbroken'}`;$('status').textContent=`${$('cohort').value.toUpperCase()} · ${index} / ${frames.length-1} · ${s.status}`;$('seats').replaceChildren();
s.players.forEach((p,i)=>{let box=document.createElement('div');box.className='seat'+(i===s.activePlayerIndex?' active':'');let title=document.createElement('strong');title.textContent=`${p.name} · bid ${p.bid===null?'—':p.bid===0?'nil':p.bid} · tricks ${p.tricksWon}`;let model=document.createElement('div');model.className='model muted';model.textContent=models[i];let hand=document.createElement('div');hand.className='cards';p.hand.forEach(c=>{if($('reveal').checked)hand.append(card(c));else{let back=document.createElement('span');back.className='card';back.textContent='▧';hand.append(back);}});box.append(title,model,hand);$('seats').append(box);});
$('trick').replaceChildren();(s.plays.length?s.plays:s.lastTrick?.plays||[]).forEach(p=>{let e=document.createElement('span');e.className='play';e.append(card(p.card));let t=document.createElement('div');t.textContent=s.players.find(x=>x.id===p.playerId)?.name||p.playerId;e.append(t);$('trick').append(e);});
const call=f.decision?.call;$('decision').textContent=f.kind==='INITIAL'?'Initial deal':`${f.player}: ${JSON.stringify(f.action)} · ${f.decision?.kind}${call?` · model ${call.latency_ms} ms · cooldown ${call.cooldown_seconds}s`:''}`;$('log').textContent=(f.newLog||[]).map(x=>JSON.stringify(x)).join('\n');}
function stop(){if(timer)clearInterval(timer);timer=null;$('play').textContent='Play';}
function step(n){index=Math.max(0,Math.min(frames.length-1,index+n));render();if(index===frames.length-1)stop();}
function play(){if(timer){stop();return;}if(index===frames.length-1)index=0;timer=setInterval(()=>step(1),Number($('speed').value));$('play').textContent='Pause';}
function choose(){stop();const rows=data[$('cohort').value];models=rows[0].models;$('outcome').textContent=`Pilot result: ${rows.at(-1).status||'pending'} · Recorded actions, not a fresh inference run. ${rows.some(r=>r.kind==='RESUME')?'Resumed after token-budget amendment.':''}`;frames=rows.filter(f=>f.snapshot);index=0;$('seek').max=frames.length-1;render();}
Object.keys(data).forEach(k=>{let o=document.createElement('option');o.value=k;o.textContent=k;$('cohort').append(o);});$('cohort').onchange=choose;$('play').onclick=play;$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);$('seek').oninput=()=>{index=Number($('seek').value);render();};$('reveal').onchange=render;$('clean').onclick=()=>document.body.classList.toggle('clean');$('speed').onchange=stop;document.onkeydown=e=>{if(e.code==='Space'){e.preventDefault();play();}if(e.code==='ArrowRight')step(1);if(e.code==='ArrowLeft')step(-1);if(e.key.toLowerCase()==='c')document.body.classList.toggle('clean');};choose();
</script></html>'''
(root/'Whiz_100_Baseline_Replay.html').write_text(html.replace('__DATA__',data))
print(root/'Whiz_100_Baseline_Replay.html')
